//! The big-digit fonts F3, F5 and F7 (DESIGN.md §4.2), generated by the
//! segment and corner rule.

/// A digit font: glyphs are `h` rows tall and `h` cells wide.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Font {
    h: usize,
}

pub const F3: Font = Font { h: 3 };
pub const F5: Font = Font { h: 5 };
pub const F7: Font = Font { h: 7 };

/// Segments a to g as bits 0 to 6.
const A: u8 = 1;
const B: u8 = 2;
const C: u8 = 4;
const D: u8 = 8;
const E: u8 = 16;
const F: u8 = 32;
const G: u8 = 64;

fn segments(ch: char) -> Option<u8> {
    Some(match ch {
        '0' => A | B | C | D | E | F,
        '1' => B | C,
        '2' => A | B | D | E | G,
        '3' => A | B | C | D | G,
        '4' => B | C | F | G,
        '5' => A | C | D | F | G,
        '6' => A | C | D | E | F | G,
        '7' => A | B | C,
        '8' => A | B | C | D | E | F | G,
        '9' => A | B | C | D | F | G,
        '-' => G,
        _ => return None,
    })
}

/// Arms that meet in a corner cell, to the character.
fn corner(right: bool, left: bool, up: bool, down: bool) -> char {
    match (right, left, up, down) {
        (false, false, false, false) => ' ',
        (true, false, false, false) => '╺',
        (false, true, false, false) => '╸',
        (false, false, true, false) => '╹',
        (false, false, false, true) => '╻',
        (true, false, false, true) => '┏',
        (false, true, false, true) => '┓',
        (true, false, true, false) => '┗',
        (false, true, true, false) => '┛',
        (true, false, true, true) => '┣',
        (false, true, true, true) => '┫',
        (false, false, true, true) => '┃',
        // Not reachable with the segment sets above; a full cross is plain.
        _ => '╋',
    }
}

impl Font {
    /// Glyph height, which is also the width of a digit.
    pub fn height(self) -> usize {
        self.h
    }

    /// Width of one glyph.
    pub fn glyph_width(self, ch: char) -> usize {
        if ch == '.' { 1 } else { self.h }
    }

    /// Width of `text`: glyphs plus one blank column between every two.
    pub fn width(self, text: &str) -> usize {
        let glyphs: usize = text.chars().map(|ch| self.glyph_width(ch)).sum();
        glyphs + text.chars().count().saturating_sub(1)
    }

    /// Column where the glyph for character `index` of `text` starts.
    pub fn start_of(self, text: &str, index: usize) -> usize {
        text.chars()
            .take(index)
            .map(|ch| self.glyph_width(ch) + 1)
            .sum()
    }

    /// The `h` rows of one glyph. Characters without a glyph are blank.
    pub fn glyph(self, ch: char) -> Vec<String> {
        let h = self.h;
        if ch == '.' {
            let mut rows = vec![" ".to_string(); h];
            rows[h - 1] = ".".into();
            return rows;
        }
        let Some(seg) = segments(ch) else {
            return vec![" ".repeat(h); h];
        };
        let has = |s: u8| seg & s != 0;
        let mid = h / 2;
        let last = h - 1;
        let mut grid = vec![vec![' '; h]; h];
        if ch == '1' {
            // One vertical in the middle column.
            for (row, cells) in grid.iter_mut().enumerate() {
                cells[h / 2] = match row {
                    0 => '╻',
                    r if r == last => '╹',
                    _ => '┃',
                };
            }
        } else {
            // Horizontal segments between the corner cells, vertical ones
            // between the horizontal rows.
            for (row, cells) in grid.iter_mut().enumerate() {
                let horizontal = match row {
                    0 => has(A),
                    r if r == mid => has(G),
                    r if r == last => has(D),
                    _ => false,
                };
                if horizontal {
                    cells[1..h - 1].fill('━');
                }
                if row > 0 && row < last {
                    let (left, right) = if row < mid {
                        (has(F), has(B))
                    } else {
                        (has(E), has(C))
                    };
                    if row != mid {
                        cells[0] = if left { '┃' } else { ' ' };
                        cells[h - 1] = if right { '┃' } else { ' ' };
                    }
                }
            }
            grid[0][0] = corner(has(A), false, false, has(F));
            grid[0][h - 1] = corner(false, has(A), false, has(B));
            grid[mid][0] = corner(has(G), false, has(F), has(E));
            grid[mid][h - 1] = corner(false, has(G), has(B), has(C));
            grid[last][0] = corner(has(D), false, has(E), false);
            grid[last][h - 1] = corner(false, has(D), has(C), false);
        }
        grid.into_iter()
            .map(|cells| cells.into_iter().collect())
            .collect()
    }

    /// `text` in this font: `h` rows, one blank column between glyphs.
    pub fn render(self, text: &str) -> Vec<String> {
        let mut rows = vec![String::new(); self.h];
        for (index, ch) in text.chars().enumerate() {
            for (row, glyph_row) in self.glyph(ch).into_iter().enumerate() {
                if index > 0 {
                    rows[row].push(' ');
                }
                rows[row].push_str(&glyph_row);
            }
        }
        rows
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn golden(name: &str) -> Vec<String> {
        let path = format!(
            "{}/../../tests/golden/{name}.txt",
            env!("CARGO_MANIFEST_DIR")
        );
        std::fs::read_to_string(path)
            .unwrap()
            .lines()
            .map(|line| line.trim_end().to_string())
            .collect()
    }

    fn check(font: Font, name: &str) {
        let rows: Vec<String> = font
            .render("0123456789.-")
            .into_iter()
            .map(|row| row.trim_end().to_string())
            .collect();
        assert_eq!(rows, golden(name));
    }

    #[test]
    fn ui_17_f3_matches_its_golden() {
        check(F3, "font-f3");
    }

    #[test]
    fn ui_17_f5_matches_its_golden() {
        check(F5, "font-f5");
    }

    #[test]
    fn ui_17_f7_matches_its_golden() {
        check(F7, "font-f7");
    }

    #[test]
    fn ui_15_widths_follow_the_glyph_plus_gap_rule() {
        assert_eq!(F3.width("4.998"), 17);
        assert_eq!(F3.width("12.345"), 21);
        assert_eq!(F3.start_of("05.00", 1), 4);
        assert_eq!(F7.width("4.998"), 4 * 7 + 1 + 4);
    }
}
